.admin-shell {
        max-width: 1100px;
        margin: 40px auto;
        padding: 24px;
      }
      .admin-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 30px;
      }
      .admin-tabs {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        margin: 24px 0;
      }
      .admin-shell button {
        cursor: pointer;
      }
      .admin-panel {
        background: #172019;
        border: 1px solid #a6c17f22;
        padding: 24px;
        border-radius: 16px;
      }
      .admin-shell input {
        width: 100%;
        margin: 8px 0 16px;
        padding: 12px;
        background: #101710;
        color: #d8e8be;
        border: 1px solid #77995b66;
        border-radius: 8px;
      }
      .admin-shell textarea {
        min-height: 220px;
        font: 12px monospace;
      }
      .admin-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 18px;
      }
      .admin-row {
        padding: 12px 0;
        border-bottom: 1px solid #80996022;
        display: flex;
        justify-content: space-between;
        gap: 10px;
      }
      .admin-actions {
        display: flex;
        gap: 8px;
        flex-wrap: wrap;
        margin: 16px 0;
      }
      .admin-message {
        white-space: pre-wrap;
        color: #efbc93;
        margin: 14px 0;
      }
      .admin-shell pre {
        overflow: auto;
        max-height: 400px;
        font-size: 12px;
      }
      .admin-shell a {
        color: #c6e993;
      }
      @media (max-width: 700px) {
        .admin-grid {
          grid-template-columns: 1fr;
        }
        .admin-shell {
          margin: 0;
          padding: 16px;
        }
      }
